from itertools import permutations

def reorganize_string(s):
    for perm in set(permutations(s)):           # every distinct permutation
        valid = all(perm[i] != perm[i + 1] for i in range(len(perm) - 1))
        if valid:
            return ''.join(perm)
    return ''

