import heapq
from collections import Counter

def reorganize_string(s):
    n = len(s)
    counts = Counter(s)
    if max(counts.values()) > (n + 1) // 2:
        return ''                                    # infeasible: too many of one character

    heap = [(-cnt, ch) for ch, cnt in counts.items()]
    heapq.heapify(heap)
    result = []
    while heap:
        cnt, ch = heapq.heappop(heap)
        if result and result[-1] == ch:               # avoid repeating the last placed character
            if not heap:
                return ''
            cnt2, ch2 = heapq.heappop(heap)
            result.append(ch2)
            if cnt2 + 1 < 0:
                heapq.heappush(heap, (cnt2 + 1, ch2))
            heapq.heappush(heap, (cnt, ch))
        else:
            result.append(ch)
            if cnt + 1 < 0:
                heapq.heappush(heap, (cnt + 1, ch))
    return ''.join(result)

