import java.util.*;

public class Main {
    static String reorganizeString(String s) {
        int n = s.length();
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : s.toCharArray()) counts.merge(c, 1, Integer::sum);
        for (int cnt : counts.values()) {
            if (cnt > (n + 1) / 2) return "";              // infeasible: too many of one character
        }

        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (Map.Entry<Character, Integer> e : counts.entrySet()) heap.offer(new int[]{e.getValue(), e.getKey()});

        StringBuilder result = new StringBuilder();
        while (!heap.isEmpty()) {
            int[] first = heap.poll();
            char ch = (char) first[1];
            if (result.length() > 0 && result.charAt(result.length() - 1) == ch) {   // avoid a repeat
                if (heap.isEmpty()) return "";
                int[] second = heap.poll();
                result.append((char) second[1]);
                if (second[0] - 1 > 0) heap.offer(new int[]{second[0] - 1, second[1]});
                heap.offer(first);
            } else {
                result.append(ch);
                if (first[0] - 1 > 0) heap.offer(new int[]{first[0] - 1, first[1]});
            }
        }
        return result.toString();
    }
}

