#include <bits/stdc++.h>
using namespace std;

string reorganizeString(string s) {
    int n = s.size();
    unordered_map<char,int> counts;
    for (char c : s) counts[c]++;
    for (auto& [ch, cnt] : counts) if (cnt > (n + 1) / 2) return "";   // infeasible

    priority_queue<pair<int,char>> heap;
    for (auto& [ch, cnt] : counts) heap.push({cnt, ch});

    string result;
    while (!heap.empty()) {
        auto [cnt, ch] = heap.top(); heap.pop();
        if (!result.empty() && result.back() == ch) {         // avoid a repeat
            if (heap.empty()) return "";
            auto [cnt2, ch2] = heap.top(); heap.pop();
            result += ch2;
            if (cnt2 - 1 > 0) heap.push({cnt2 - 1, ch2});
            heap.push({cnt, ch});
        } else {
            result += ch;
            if (cnt - 1 > 0) heap.push({cnt - 1, ch});
        }
    }
    return result;
}
